// ── Tabs: Eclipse Mangas / MangaDex / Favoritos (2026-09-26) ─────────────
// Eclipse Mangas = mangas translated by the team, read from
// eclipse_mangas.json (GitLab senpai1940/juegos, via the Worker). Shape:
// [{id, titulo, portada, descripcion, estado, categorias[],
//   capitulos:[{num, titulo, fecha, paginas:[url…]}]}]
// Each tab has its own grid so a background MangaDex fetch never overwrites
// what another tab is showing.
const ECLIPSE_MANGAS_RAW = "https://gitlab.com/senpai1940/juegos/-/raw/main/eclipse_mangas.json";
mangaState.eclipse = null;
mangaState.eclipseFavorites = (() => {
    try { return JSON.parse(localStorage.getItem("eclipseMangaFavorites") || "[]"); } catch { return []; }
})();
mangaState.eclipseReader = null;
let _mdBooted = false;

function _escM(v) {
    return String(v ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

function _eclipseImg(u) {
    return u ? (typeof cachedImageUrl === "function" ? cachedImageUrl(u) : u) : "";
}

let _eclipseFetchPromise = null;
function fetchEclipseMangas() {
    if (Array.isArray(mangaState.eclipse)) return Promise.resolve(mangaState.eclipse);
    // Several init paths call this at once — share one request.
    return _eclipseFetchPromise || (_eclipseFetchPromise = _loadEclipseMangas().finally(() => { _eclipseFetchPromise = null; }));
}

async function _loadEclipseMangas() {
    try {
        const url = (typeof _glRawToWorker === "function" && _glRawToWorker(ECLIPSE_MANGAS_RAW)) || ECLIPSE_MANGAS_RAW;
        const res = await fetch(url);
        const data = res.ok ? await res.json() : [];
        mangaState.eclipse = Array.isArray(data) ? data : (data.mangas || []);
    } catch (e) {
        console.warn("[eclipse-mangas] no se pudo leer eclipse_mangas.json:", e);
        mangaState.eclipse = [];
    }
    return mangaState.eclipse;
}

function _eclipseCardHTML(m) {
    const isFav = mangaState.eclipseFavorites.includes(m.id);
    return `
        <div class="manga-card" onclick="showEclipseMangaDetail('${_escM(m.id)}')" data-eclipse-id="${_escM(m.id)}">
            <div class="manga-cover-wrapper">
                <img src="${_escM(_eclipseImg(m.portada))}" class="manga-cover" alt="${_escM(m.titulo)}" loading="lazy"
                     onerror="this.src='https://placehold.co/300x420/2d2d2d/fff?text=Sin+portada'">
                <div class="manga-cover-overlay">
                    <span class="manga-status-badge badge-neutral">Eclipse</span>
                    ${isFav ? '<span class="manga-fav-indicator"><i class="bi bi-heart-fill"></i></span>' : ""}
                </div>
            </div>
            <div class="manga-info">
                <h6 class="manga-title" title="${_escM(m.titulo)}">${_escM(m.titulo)}</h6>
                <div class="manga-tags-mini">
                    ${(m.categorias || []).slice(0, 3).map(c => `<span class="manga-tag-chip">${_escM(c)}</span>`).join("")}
                </div>
            </div>
        </div>`;
}

const _LOADING_HTML = '<div class="manga-empty-state"><div class="loading-spinner-sm"></div></div>';

async function renderEclipseGrid() {
    const grid = document.getElementById("eclipseMangaGrid");
    if (!grid) return;
    grid.innerHTML = _LOADING_HTML;
    const mangas = await fetchEclipseMangas();
    grid.innerHTML = mangas.length
        ? mangas.map(_eclipseCardHTML).join("")
        : `<div class="manga-empty-state">
               <i class="bi bi-stars"></i>
               <p>Próximamente</p>
               <small class="text-muted">Acá van a estar los mangas traducidos por Eclipse Zone.
               Mientras tanto, mirá la pestaña MangaDex.</small>
           </div>`;
}

async function renderMangaFavorites() {
    const grid = document.getElementById("favMangaGrid");
    if (!grid) return;
    const mdIds = mangaState.favorites, ecIds = mangaState.eclipseFavorites;
    if (!mdIds.length && !ecIds.length) {
        grid.innerHTML = '<div class="manga-empty-state"><i class="bi bi-heart"></i><p>No tienes mangas favoritos</p></div>';
        return;
    }
    grid.innerHTML = _LOADING_HTML;
    const eclipse = (await fetchEclipseMangas()).filter(m => ecIds.includes(m.id));
    // Fetched by id — before this only the loaded MangaDex page was filtered,
    // so favorites on other pages never showed up.
    let md = [];
    if (mdIds.length) {
        try {
            const data = await mdFetch("/manga", {
                ids: mdIds.slice(0, 100), limit: 100,
                includes: ["cover_art"], contentRating: MD_ALL_RATINGS,
            });
            md = data.data || [];
        } catch (e) {
            console.error("Error cargando favoritos de MangaDex:", e);
        }
    }
    // renderMangaDexGrid only knows #mangaGrid: render there, copy, restore.
    const mdGrid = document.getElementById("mangaGrid");
    const prev = mdGrid.innerHTML;
    renderMangaDexGrid(md);
    const mdHTML = md.length ? mdGrid.innerHTML : "";
    mdGrid.innerHTML = prev;
    if (mangaState.currentTab === "favorites") grid.innerHTML = eclipse.map(_eclipseCardHTML).join("") + mdHTML;
}

function switchMangasTab(tab) {
    if (tab === "all") tab = "mangadex";         // legacy value
    mangaState.currentTab = tab;
    mangaState.localPage = 1;
    document.querySelectorAll("#mangasContent .favorites-tab").forEach(t =>
        t.classList.toggle("active", t.dataset.tab === tab));
    // setProperty(..., "important"): Bootstrap's .d-flex is display:flex !important.
    const show = (id, on) => {
        const el = document.getElementById(id);
        if (el) on ? el.style.removeProperty("display") : el.style.setProperty("display", "none", "important");
    };
    show("eclipseMangaGrid", tab === "eclipse");
    show("mangaGrid", tab === "mangadex");
    show("mangaPaginationContainer", tab === "mangadex");
    show("favMangaGrid", tab === "favorites");
    // Search / filters / sort only apply to MangaDex.
    show("mangaTopActions", tab === "mangadex");

    if (tab === "eclipse") return void renderEclipseGrid();
    if (tab === "favorites") return void renderMangaFavorites();
    // MangaDex loads only when its tab is opened for the first time.
    if (!_mdBooted) {
        _mdBooted = true;
        loadMangaTags().finally(() => fetchMangas(true));
    } else if (!mangaState.results.length && !mangaState.loading) {
        fetchMangas(true);
    }
}

function showEclipseMangaDetail(id) {
    const m = (mangaState.eclipse || []).find(x => x.id === id);
    const panel = document.getElementById("mangaDetailPanel");
    const body = document.getElementById("mangaDetailBody");
    if (!m || !panel || !body) return;
    try { history.pushState({ type: "manga-detail", eclipseId: id }, "", location.pathname); } catch {}
    const wasOpen = panel.classList.contains("show");
    panel.classList.add("show");
    if (!wasOpen) (typeof lockBodyScroll === "function" ? lockBodyScroll() : (document.body.style.overflow = "hidden"));
    const isFav = mangaState.eclipseFavorites.includes(id);
    const caps = [...(m.capitulos || [])].sort((a, b) => parseFloat(b.num) - parseFloat(a.num));
    body.innerHTML = `
        <div class="manga-detail-header">
            <img src="${_escM(_eclipseImg(m.portada))}" class="manga-detail-cover" alt="${_escM(m.titulo)}">
            <div class="manga-detail-meta">
                <h4 class="manga-detail-title">${_escM(m.titulo)}</h4>
                <div class="manga-detail-badges">
                    <span class="manga-status-badge badge-neutral">Eclipse</span>
                    ${m.estado ? `<span class="manga-status-badge badge-neutral">${_escM(m.estado)}</span>` : ""}
                </div>
                <button id="mangaFavBtn" class="manga-action-btn ${isFav ? "active-fav" : ""}"
                        onclick="toggleEclipseMangaFavorite('${_escM(id)}')">
                    <i class="bi bi-heart${isFav ? "-fill" : ""}"></i> ${isFav ? "En favoritos" : "Añadir favorito"}
                </button>
            </div>
        </div>
        ${m.descripcion ? `<p class="manga-detail-desc">${_escM(m.descripcion)}</p>` : ""}
        <div class="manga-chapters-list">
            ${caps.length ? caps.map(c => `
                <div class="manga-chapter-item" onclick="openEclipseChapter('${_escM(id)}','${_escM(c.num)}')">
                    <span>Cap. ${_escM(c.num)}${c.titulo ? ` — ${_escM(c.titulo)}` : ""}</span>
                    ${c.fecha ? `<small class="text-muted">${_escM(c.fecha)}</small>` : ""}
                </div>`).join("") : '<p class="text-muted text-center p-4">Todavía no hay capítulos.</p>'}
        </div>`;
}

function openEclipseChapter(mangaId, num, replace = false) {
    const m = (mangaState.eclipse || []).find(x => x.id === mangaId);
    const caps = [...((m && m.capitulos) || [])].sort((a, b) => parseFloat(a.num) - parseFloat(b.num));
    const idx = caps.findIndex(c => String(c.num) === String(num));
    const reader = document.getElementById("mangaReader");
    if (idx < 0 || !reader) return;
    const cap = caps[idx];
    currentChapterId = `eclipse:${mangaId}:${cap.num}`;
    currentChapterNum = `Cap. ${cap.num}`;
    currentMangaTitle = m.titulo;
    _readerReloadTried = false;
    try {
        const state = { type: "manga-reader", eclipseId: mangaId, chapterNum: cap.num };
        replace ? history.replaceState(state, "", location.pathname) : history.pushState(state, "", location.pathname);
    } catch {}
    reader.classList.add("show");
    document.getElementById("readerTitle").textContent = `${m.titulo} — Cap. ${cap.num}`;
    mangaState.readerPages = (cap.paginas || []).map(u => ({ primary: _eclipseImg(u), fallback: u }));
    mangaState.eclipseReader = { mangaId, caps, idx };
    if (!mangaState.readerPages.length) {
        document.getElementById("readerPages").innerHTML =
            '<p class="text-muted text-center p-4">Este capítulo no tiene páginas disponibles.</p>';
        return;
    }
    let saved = null;
    try { saved = JSON.parse(localStorage.getItem("mangaReadingProgress") || "{}")[currentChapterId]; } catch {}
    currentPageIndex = saved && saved.page < mangaState.readerPages.length ? saved.page : 0;
    renderSinglePage();
    initReaderGestures();
}

function eclipseStepChapter(dir) {
    const r = mangaState.eclipseReader;
    const target = r && r.caps[r.idx + dir];
    if (!target) return void _toast(dir > 0 ? "📖 No hay más capítulos disponibles" : "📖 Es el primer capítulo");
    openEclipseChapter(r.mangaId, target.num, true);
}

function toggleEclipseMangaFavorite(id) {
    const favs = mangaState.eclipseFavorites, i = favs.indexOf(id);
    i === -1 ? (favs.push(id), _toast("Añadido a favoritos ❤️")) : (favs.splice(i, 1), _toast("Eliminado de favoritos"));
    try { localStorage.setItem("eclipseMangaFavorites", JSON.stringify(favs)); } catch {}
    const btn = document.getElementById("mangaFavBtn"), isFav = favs.includes(id);
    if (btn) {
        btn.className = "manga-action-btn " + (isFav ? "active-fav" : "");
        btn.innerHTML = `<i class="bi bi-heart${isFav ? "-fill" : ""}"></i> ${isFav ? "En favoritos" : "Añadir favorito"}`;
    }
    if (mangaState.currentTab === "eclipse") renderEclipseGrid();
    else if (mangaState.currentTab === "favorites") renderMangaFavorites();
}

Object.assign(window, {
    switchMangasTab, fetchEclipseMangas, renderEclipseGrid, renderMangaFavorites,
    showEclipseMangaDetail, openEclipseChapter, eclipseStepChapter, toggleEclipseMangaFavorite,
});
